import type { ASTPath } from 'jscodeshift';
import {
  applyImportRules,
  isReference,
  vendorTransform,
  type ModuleRule,
  type VendorContext,
  type VendorTransform,
} from './engine';
import { ATLAS } from './shared';

/**
 * Hand-rolled OpenID Connect → `@atlasauth/backend` `oidc.*`.
 *
 * A relying party written by hand (or on `openid-client` / `jose`) does the same
 * five jobs every time: discover the provider, build the authorize URL with
 * state + nonce + PKCE, exchange the code, verify the ID token against the
 * provider's keys, and build the logout URL. `oidc.start()`, `oidc.callback()`,
 * `oidc.verifyIdToken()` and `oidc.logoutUrl()` do all five, so this codemod does
 * not guess at your session or user code. It finds each of those steps and:
 *
 *  - adds `import { oidc } from '@atlasauth/backend'` to the file;
 *  - marks every step with a `TODO(atlas-migrate)` naming the exact call that
 *    replaces it, and reports it with file:line;
 *  - leaves the old code in place until you delete it (it may be doing more
 *    than the OIDC dance), so the result always type-checks and runs.
 *
 * Three entry points share the passes: `openid-client` (only that library),
 * `jose` (only ID-token verification code) and `generic-oidc` (all of them plus
 * fetch-based flows found by what the code does).
 */

type Flavor = 'openid-client' | 'jose' | 'generic-oidc';

const START = 'oidc.start({ issuer, clientId, redirectUri, secret }) returns { url, cookie }: redirect to url and send cookie as Set-Cookie (state, nonce and PKCE are generated and kept in a sealed cookie)';
const CALLBACK = 'oidc.callback({ issuer, clientId, clientSecret, redirectUri, query, cookie, secret }) checks state, exchanges the code with PKCE, verifies the ID token (alg pinned, iss, aud, azp, nonce, at_hash) and returns { sub, namespacedSub, email, emailVerified, claims, idToken, accessToken, refreshToken }';
const LOGOUT = 'oidc.logoutUrl({ issuer, clientId, postLogoutRedirectUri, idTokenHint }) builds the end_session URL from discovery';
const VERIFY = 'oidc.verifyIdToken(idToken, { issuer, clientId, nonce, accessToken }) runs the same checks on an ID token you obtained yourself';
const DISCOVERY = 'discovery (and its cache) is built into oidc.start / oidc.callback / oidc.logoutUrl';
const JWKS = 'the signing keys are fetched, cached and refetched on an unknown kid (rate limited) by oidc.callback / oidc.verifyIdToken';
const PKCE = 'state, nonce and the PKCE verifier/challenge are generated by oidc.start and read back by oidc.callback';

/** `openid-client` exports → what replaces them. v5 (Issuer, generators, TokenSet) and v6 (functions). */
const OPENID_CLIENT: Record<string, string> = {
  Issuer: `Issuer.discover(...) / new Issuer(...): ${DISCOVERY}`,
  BaseClient: 'the Client object is not needed: pass issuer + clientId (+ clientSecret) to each oidc.* call',
  Client: 'the Client object is not needed: pass issuer + clientId (+ clientSecret) to each oidc.* call',
  generators: PKCE,
  custom: 'custom HTTP options: oidc.* accept fetchImpl for a custom fetch',
  TokenSet: `the token set is the object oidc.callback returns: ${CALLBACK}`,
  discovery: DISCOVERY,
  buildAuthorizationUrl: START,
  authorizationCodeGrant: CALLBACK,
  buildEndSessionUrl: LOGOUT,
  randomPKCECodeVerifier: PKCE,
  calculatePKCECodeChallenge: PKCE,
  randomState: PKCE,
  randomNonce: PKCE,
  fetchUserInfo: 'the ID token already carries sub, email, email_verified and name (identity.claims); call the userinfo endpoint yourself only for extra claims',
  refreshTokenGrant: 'oidc.callback returns identity.refreshToken; refresh by POSTing grant_type=refresh_token to the token_endpoint from discovery',
  Configuration: 'the Configuration object is not needed: pass issuer + clientId (+ clientSecret) to each oidc.* call',
};

const RULES: readonly ModuleRule[] = [
  {
    match: 'openid-client',
    named: Object.fromEntries(Object.entries(OPENID_CLIENT).map(([k, v]) => [k, { manual: `'${k}' from 'openid-client': ${v}` }])),
    otherNamed: `replace with the matching oidc.* call: ${START}; ${CALLBACK}`,
    whole: `openid-client: replace the flow with oidc.start / oidc.callback / oidc.logoutUrl`,
  },
];

/** Method names on an openid-client Client/Issuer that mark a step of the flow. */
const MEMBER_CALLS: Record<string, string> = {
  discover: DISCOVERY,
  authorizationUrl: START,
  callbackParams: 'the callback query goes to oidc.callback as `query` (a URLSearchParams, URL string or parsed object)',
  callback: CALLBACK,
  oauthCallback: CALLBACK,
  grant: 'oidc.callback performs the authorization_code grant; for refresh_token POST to the token_endpoint from discovery',
  refresh: 'oidc.callback returns identity.refreshToken; refresh by POSTing grant_type=refresh_token to the token_endpoint from discovery',
  endSessionUrl: LOGOUT,
  userinfo: 'the ID token already carries sub, email, email_verified and name (identity.claims)',
  validateIdToken: VERIFY,
};

function importedFrom(ctx: VendorContext, spec: string): boolean {
  return ctx.root.find(ctx.j.ImportDeclaration, { source: { value: spec } }).length > 0 || requires(ctx, spec);
}

function requires(ctx: VendorContext, spec: string): boolean {
  const { j } = ctx;
  return (
    ctx.root
      .find(j.CallExpression, { callee: { type: 'Identifier', name: 'require' } })
      .filter((p) => {
        const a = p.node.arguments[0] as { value?: unknown } | undefined;
        return a?.value === spec;
      }).length > 0
  );
}

function ensureOidcImport(ctx: VendorContext): void {
  ctx.ensureImport(ATLAS.backend, 'oidc');
}

/** openid-client: imports + the member calls of the flow. */
function openidClientPass(ctx: VendorContext): boolean {
  if (!importedFrom(ctx, 'openid-client')) return false;
  const { j, root } = ctx;
  applyImportRules(ctx, RULES);
  let found = false;
  root.find(j.CallExpression).forEach((path) => {
    const callee = path.node.callee as { type: string; property?: { type: string; name?: string }; computed?: boolean };
    if (callee.type !== 'MemberExpression' && callee.type !== 'OptionalMemberExpression') return;
    if (callee.computed || callee.property?.type !== 'Identifier') return;
    const note = MEMBER_CALLS[callee.property.name!];
    if (!note) return;
    ctx.manual(path as ASTPath, `${callee.property.name}(): ${note}`);
    found = true;
  });
  root.find(j.MemberExpression).forEach((path) => {
    const node = path.node as { object: { type: string; name?: string }; property: { type: string; name?: string } };
    if (node.object.type === 'Identifier' && node.object.name === 'generators' && node.property.type === 'Identifier') {
      ctx.manual(path as ASTPath, `generators.${node.property.name}(): ${PKCE}`);
      found = true;
    }
  });
  return found || ctx.changed;
}

/** jose: jwtVerify / createRemoteJWKSet in a file that verifies an OIDC ID token. */
function josePass(ctx: VendorContext, source: string): boolean {
  if (!importedFrom(ctx, 'jose') && !/\brequire\(['"]jose['"]\)/.test(source)) return false;
  if (!/\b(nonce|id_?token|openid|oidc|issuer)\b/i.test(source)) return false;
  const { j, root } = ctx;
  let found = false;
  const names = new Set<string>();
  root.find(j.ImportDeclaration, { source: { value: 'jose' } }).forEach((p) => {
    for (const s of p.node.specifiers ?? []) if (s.type === 'ImportSpecifier') names.add(s.local?.name ?? s.imported.name);
  });
  root.find(j.CallExpression).forEach((path) => {
    const callee = path.node.callee as { type: string; name?: string; property?: { name?: string } };
    const name = callee.type === 'Identifier' ? callee.name : callee.property?.name;
    if (!name) return;
    if (name === 'jwtVerify' && (callee.type !== 'Identifier' || names.has(name))) {
      ctx.manual(
        path as ASTPath,
        `jwtVerify(): if this verifies an OIDC ID token, ${VERIFY}. If it verifies a session or access token, use AtlasBackend#verify() from @atlasauth/backend (it checks the issuer, audience and expiry against the instance's keys)`,
      );
      found = true;
    } else if (name === 'createRemoteJWKSet' && (callee.type !== 'Identifier' || names.has(name))) {
      ctx.manual(path as ASTPath, `createRemoteJWKSet(): ${JWKS}`);
      found = true;
    }
  });
  return found;
}

/** Steps of a flow written with fetch/axios/http: found by what the code does. */
function handRolledPass(ctx: VendorContext): boolean {
  const { j, root } = ctx;
  let found = false;
  // One marker per kind of step per file: a flow touches PKCE in many lines, the advice is the same.
  const done = new Set<string>();
  const mark = (path: ASTPath, message: string) => {
    found = true;
    if (done.has(message)) return;
    done.add(message);
    ctx.manual(path, message);
  };
  const check = (path: ASTPath, text: string) => {
    if (/\.well-known\/openid-configuration/.test(text)) mark(path, `OIDC discovery by hand: ${DISCOVERY}`);
    else if (/^(code_challenge|code_challenge_method|code_verifier)$/.test(text)) mark(path, `PKCE by hand: ${PKCE}`);
    else if (/^(authorization_code)$/.test(text) || /grant_type=authorization_code/.test(text)) mark(path, `code exchange by hand: ${CALLBACK}`);
    else if (/^(end_session_endpoint)$/.test(text)) mark(path, `logout URL by hand: ${LOGOUT}`);
    else if (/^(jwks_uri)$/.test(text)) mark(path, `JWKS fetching by hand: ${JWKS}`);
    else if (/^(client_secret_basic|client_secret_post)$/.test(text)) mark(path, 'token-endpoint client authentication is chosen by oidc.callback (clientAuth: client_secret_basic | client_secret_post | none)');
  };
  const literalText = (v: unknown) => (typeof v === 'string' ? v : undefined);
  root.find(j.StringLiteral).forEach((p) => {
    const parent = p.parent?.node as { type?: string } | undefined;
    if (parent && /Import|Export/.test(parent.type ?? '')) return;
    const t = literalText(p.node.value);
    if (t) check(p as ASTPath, t);
  });
  root.find(j.TemplateLiteral).forEach((p) => {
    const t = p.node.quasis.map((q) => q.value.raw).join('${}');
    if (/\.well-known\/openid-configuration/.test(t) || /grant_type=authorization_code/.test(t)) check(p as ASTPath, t);
  });
  root.find(j.MemberExpression).forEach((p) => {
    const node = p.node as { computed?: boolean; property: { type: string; name?: string } };
    if (node.computed || node.property.type !== 'Identifier') return;
    const name = node.property.name!;
    if (name === 'end_session_endpoint') mark(p as ASTPath, `logout URL by hand: ${LOGOUT}`);
    else if (name === 'jwks_uri') mark(p as ASTPath, `JWKS fetching by hand: ${JWKS}`);
  });
  root.find(j.Identifier).forEach((p) => {
    if (!isReference(p)) {
      // object keys / property names: `{ code_challenge: ... }`, `url.searchParams.set('code_challenge', …)` handled by the string pass
      const parent = p.parent?.node as { type?: string; key?: unknown } | undefined;
      if (parent && (parent.type === 'ObjectProperty' || parent.type === 'Property') && parent.key === p.node) check(p as ASTPath, p.node.name);
      return;
    }
    if (/^(codeVerifier|code_verifier|codeChallenge)$/.test(p.node.name)) mark(p as ASTPath, `PKCE by hand: ${PKCE}`);
  });
  return found;
}

function makeTransform(flavor: Flavor): VendorTransform {
  return vendorTransform({
    mightApply: (source) => {
      if (flavor === 'openid-client') return /openid-client/.test(source);
      if (flavor === 'jose') return /\bjose\b/.test(source);
      return /openid-client|\bjose\b|openid-configuration|code_challenge|code_verifier|authorization_code|end_session_endpoint|jwks_uri/.test(source);
    },
    run(ctx) {
      const source = ctx.root.toSource();
      let found = false;
      if (flavor !== 'jose') found = openidClientPass(ctx) || found;
      if (flavor !== 'openid-client') found = josePass(ctx, source) || found;
      if (flavor === 'generic-oidc') found = handRolledPass(ctx) || found;
      // The marked file gets the import, so the replacement is one edit away and `add` lists the package.
      if (found || ctx.changed) ensureOidcImport(ctx);
    },
  });
}

export const openidClientToAtlas = makeTransform('openid-client');
export const joseToAtlas = makeTransform('jose');
export const genericOidcToAtlas = makeTransform('generic-oidc');
